mapper.select:
/* selectBuyerMdAmUserSearchList */ SELECT S.ROWM, S.USER_ID, S.USER_NAME_LOC, S.PHONE_NUMBER, S.EMAIL, S.DEPARTMENT, S.DEPT_NAME, S.STATUS, S.STATUS_TEXT, S.REJECT_REASON, S.COM_CODE, (SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = S.COM_CODE) AS COM_NAME_LOC FROM ( SELECT ROWNUM ROWM, /* 순번 */ L.USER_ID, /* 사용자 ID */ L.USER_NAME_LOC, /* 사용자 이름 */ L.PHONE_NUMBER, /* 핸드폰번호 */ L.EMAIL, /* 이메일 */ L.DEPARTMENT, /* 부서코드 */ (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = L.COM_CODE AND TYPE='C001' AND CODE = L.DEPARTMENT) DEPT_NAME, /* 부서명 */ L.STATUS, /* 상태 */ decode(L.STATUS,'D','삭제','사용') AS STATUS_TEXT, /* 상태값 */ L.REJECT_REASON, /* 거절사유 (전체 탭에서 거절/삭제 구분용) */ L.COM_CODE FROM ICOMLUSR L WHERE 1=1
AND L.COM_CODE IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'BGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.TEXT1 = #{st_group_info} AND COD3.FLAG = 'Y')
AND L.COM_CODE = #{st_com_code}
AND L.COM_CODE IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'TGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.FLAG = 'Y')
AND L.COM_CODE = #{SESSION_BUYER_CODE}
AND L.STATUS IN ('C','R','D')
AND L.STATUS IN ('C','R')
AND L.USER_ID = UPPER(#{st_search_user_id})
AND L.USER_NAME_LOC LIKE '%'||#{st_search_user_name}||'%'
AND L.DEPARTMENT = #{st_btoa_user_dept_code}
AND (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = L.COM_CODE AND TYPE='C001' AND CODE = L.DEPARTMENT) LIKE '%'||#{st_btoa_user_dept_name}||'%'
ORDER BY L.REG_DATE DESC ) S

mapper.update:

 		 	/*updateBuyerMdAmUserSearchList*/
 		 	UPDATE ICOMLUSR
			SET
				STATUS					= #{st_status},
				EXPIRE_DATE			= TO_CHAR(SYSDATE,'YYYYMMDD'),
				CONFIRM_USER_ID	= #{st_user_id}
			WHERE USER_ID = #{st_change_user_id}
